    int[] parent = new int[n];
    java.util.Arrays.fill(parent, -1);
    int[] order = new int[n];
    int idx = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    stack.push(0);
    while (!stack.isEmpty()) {
        int node = stack.pop();
        order[idx++] = node;
        for (int nei : graph[node]) {
            if (nei != parent[node]) {
                parent[nei] = node;
                stack.push(nei);
            }
        }
    }

    // Bottom-up computation of time required for each subtree
    int[] time = new int[n];
    boolean[] needed = new boolean[n];
    for (int i = n - 1; i >= 0; i--) {
